SHOW server_version;
BEGIN;
CREATE SCHEMA bicdb_join_filter_control;
SET LOCAL search_path=bicdb_join_filter_control,pg_catalog;
CREATE TABLE catalog_budget_0(id INT PRIMARY KEY,c1 TEXT,c2 TEXT,c3 TEXT);
SELECT 'bicdb_join_filter_control.catalog_budget_0'::regclass::oid AS target_oid \gset
SELECT c.oid,a.attnum,a.attname,c.relname,n.nspname,
 a.attnotnull OR (t.typtype='d' AND t.typnotnull),
 a.attidentity!='' OR pg_catalog.pg_get_expr(d.adbin,d.adrelid) LIKE '%nextval(%'
 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON c.relnamespace=n.oid
 JOIN pg_catalog.pg_attribute a ON c.oid=a.attrelid
 JOIN pg_catalog.pg_type t ON a.atttypid=t.oid
 LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
 JOIN (SELECT :target_oid AS oid,1 AS attnum UNION ALL SELECT :target_oid,2
 UNION ALL SELECT :target_oid,3 UNION ALL SELECT :target_oid,4) vals
 ON c.oid=vals.oid AND a.attnum=vals.attnum WHERE c.oid IN (:target_oid) ORDER BY a.attnum;
CREATE TABLE outer_filter_l(id INT,v TEXT);
INSERT INTO outer_filter_l VALUES(1,'present'),(3,'orphan');
SELECT l.id,r.id FROM outer_filter_l l RIGHT JOIN (SELECT 1 AS id UNION ALL SELECT 2) r ON l.id=r.id WHERE l.v IS NULL ORDER BY r.id;
SELECT l.id,r.id FROM outer_filter_l l FULL JOIN (SELECT 1 AS id UNION ALL SELECT 2) r ON l.id=r.id WHERE l.v IS NULL ORDER BY r.id;
SELECT count(*) AS virtual_right_null_rows FROM pg_catalog.pg_class c RIGHT JOIN (SELECT :target_oid AS oid) r ON c.oid=r.oid WHERE c.oid IS NULL;
SELECT count(*) AS virtual_full_null_rows FROM pg_catalog.pg_class c FULL JOIN (SELECT :target_oid AS oid) r ON c.oid=r.oid WHERE c.oid IS NULL;
ROLLBACK;
